$result = eval { $test_hash->FETCH('key2') };
if ($@) { fail('Function crashed: ' . $@); } else { is($result, 'value2', 'FETCH returns correct value for multiple keys'); }

# Clean up mocks
if ($mock_hash) {
    $mock_hash->unmock('FETCH');
}

done_testing();

